		URL:        repo,
		Reference:  "v0",
		Revision:   "0000000",
		Path:       subdir,
		Files:      []string{"LICENSE", "parser.c"},
		ABI:        14,
		LocalBuild: &LocalBuild{Patch: patchPath},
	}}); err != nil {
		t.Fatal(err)
	}
	if filepath.IsLocal(patchPath) {
		writeTestFile(t, filepath.Join(root, patchPath), patch)
