// LocalBuild is how grammar-refresh turns the upstream checkout into the
// vendored files: Patch (relative to the grammars directory) is applied
// first, then the parser is regenerated when TreeSitterCLI is set.
type LocalBuild struct {
	Patch         string   `json:"patch,omitempty"`
	TreeSitterCLI string   `json:"tree_sitter_cli,omitempty"`
	GenerateArgs  []string `json:"generate_args,omitempty"`
}

// applyPatch applies patchFile to the grammar at subdir inside checkout; the
// patch's paths are relative to the grammar directory.
func applyPatch(checkout, subdir, patchFile string) error {
	args := []string{"apply"}
	if subdir != "" {
		args = append(args, "--directory="+filepath.ToSlash(subdir))
	}
	args = append(args, "--", patchFile)
	cmd := exec.Command("git", args...)
	cmd.Dir = checkout
	if out, err := cmd.CombinedOutput(); err != nil {
		return fmt.Errorf("apply %s: %w\n%s", patchFile, err, bytes.TrimSpace(out))
	}
	return nil
}

