	if lb := grammars[0].LocalBuild; lb == nil || lb.TreeSitterCLI != "0.24.7" {
		t.Fatalf("local_build = %+v", lb)
	}
}

func TestRefreshGenerateRecordsLatest(t *testing.T) {
	log := fakeNPX(t, "0.27.1", "14")
